```javascript
function postMessageToSlack(text, channel) {
  const token = 'YOUR_SLACK_API_TOKEN'; // Replace with your actual Slack API token
  const url = `https://slack.com/api/chat.postMessage?token=${token}&channel=${channel}`;

  fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
