2. In your WebApi project, create a new class that will handle the JWT token validation and retrieval of the username. For example:
```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;

public class JwtTokenHandler
{
    private readonly TokenValidationParameters _tokenValidationParameters;

    public JwtTokenHandler(string key)
    {
        _tokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            IssuerSigningKey = key,
            ClockSkew = TimeSpan.Zero
        };
    }

    public string GetUsername(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var securityToken = tokenHandler.ReadJwtToken(token, _tokenValidationParameters);
        var usernameClaim = securityToken.Claims.FirstOrDefault(c => c.Type == "username");
        return usernameClaim?.Value;
    }
}
```
3. In your WebApi controller, you can use the `JwtTokenHandler` to retrieve the username from the JWT token. For example:
```csharp
