Here's an R code snippet that checks if all non-NA elements in a character vector can be converted to numeric:

```R
# Function to check if all non-NA elements in a character vector can be converted to numeric
can_convert_to_numeric <- function(char_vector) {
  # Check if any element is NA
  if (any(is.na(char_vector))) {
    return(FALSE)
  }

  # Try converting all elements to numeric
  tryCatch({
    numeric_vector <- as.numeric(char_vector)

    # Check if any conversion failed
    if (any(is.na(numeric_vector))) {
      return(FALSE)
    } else {
      return(TRUE)
    }
  }, error = function(e) {
    return(FALSE)
  })
}

# Test the function with some examples
char_vector1 <- c("1", "2", "3", "4")
char_vector2 <- c("1", "2", "3", "4", "NA")
char_vector3 <- c("1", "2", "3", "4", "a")

print(can_convert_to_numeric(char_vector1)) # Output: TRUE
print(can_convert_to_numeric(char_vector2)) # Output: FALSE
print(can_convert_to_numeric(char_vector3)) # Output: FALSE
```

