To create a simple toast notification using React Context, follow these steps:

1. Create a ToastContext component:

```javascript
import React, { createContext, useState } from 'react';

const ToastContext = createContext({});

function ToastProvider(props) {
  const [toast, setToast] = useState(null);

  return (
    <ToastContext.Provider value={{ toast, setToast }}>
      {props.children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Create a Toast component:

```javascript
import React from 'react';
import { useContext } from 'react';

function Toast() {
  const { toast } = useContext(ToastContext);

  if (!toast) {
    return null;
  }

  return (
    <div className="toast">
      {toast}
    </div>
  );
}

export default Toast;
```

3. Use the ToastContext and Toast components in your application:

```javascript
import React from 'react';
import { ToastContext, ToastProvider, Toast } from './ToastContext';

function App() {
  return (
    <ToastProvider>
      <Toast />
      {/* ... Your other components ... */}
    </ToastProvider>
  );
}

export default App;
```

4. Display a toast notification:

In any component that uses the ToastContext, you can display a toast notification by calling the `setToast` function provided by the context:

```javascript
import React from 'react';
import { useContext } from 'react';

function MyComponent() {
  const { setToast } = useContext(ToastContext);

  const handleClick = () => {
    setToast('This is a toast notification!');
  };

  return (
    <button onClick={handleClick}>Display Toast</button>
  );
}

export default MyComponent;
```

