Here's a simple React utility that removes widows by adjusting the font size. This utility assumes that you have a container element with a fixed width and a dynamic content element inside it.

```javascript
import React, { useRef, useState } from 'react';

const WidowRemover = ({ containerRef, contentRef }) => {
  const [fontSize, setFontSize] = useState(16);

  const containerRefCurrent = useRef(null);
  const contentRefCurrent = useRef(null);

  const handleResize = () => {
    if (containerRefCurrent.current && contentRefCurrent.current) {
      const containerWidth = containerRefCurrent.current.offsetWidth;
      const contentWidth = contentRefCurrent.current.offsetWidth;

      const newFontSize = Math.max(16, containerWidth / contentWidth);

      if (newFontSize !== fontSize) {
        setFontSize(newFontSize);
