Here's a Go code snippet that implements the above logic using a table of specific negative words:

```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "no", "nothing", "none"}

func isDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && hasNotBeforeNegativeWord(word) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if word == negWord || word == "-" + negWord {
			return true
		}
	}
	return false
}

func hasNotBeforeNegativeWord(word string) bool {
	prevWord := ""
	for _, w := range strings.Split(word, " ") {
		if w == "not" {
			prevWord = "not"
			continue
		}
		if prevWord == "not" && w != "" {
			return false
		}
		prevWord = w
	}
	return true
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

This code defines two helper functions `containsNegativeWord` and `hasNotBeforeNegativeWord` to check if a given word contains a negative word or if there's a "not" before a negative word respectively. The `isDoubleNegative` function checks if the input sentence contains a double negative by iterating through its words and checking for both conditions. If both conditions are satisfied, it returns true; otherwise, it returns false.

