To achieve this, you need to update your `checkMNPStatusAPI` function to return a promise and then use the `map()` method on the `registrations` array to call the function with the desired parameters. Here's the updated code:

```javascript
import React, { useState } from 'react';

const ManageRegistrationScreen = () => {
  const [registrations, setRegistrations] = useState([]);

  async function checkMNPStatusAPI(phoneNo, index) {
    console.log('mnpphoneNo: ', phoneNo);

    var headers = new Headers();
    headers.append('Authorization', 'Bearer ' + user.getAccessToken());

    const response = await fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
      headers: headers,
      method: 'GET'
    });

    const rjson = await response.json();
    setRegistrations((prevRegistrations) => prevRegistrations.map((registration, i) => {
      if (index === i) {
        return { ...registration, mnpStatus: rjson.status };
      }
      return registration;
    }));
  }

  // Example usage:
  const examplePhoneNumbers = ['1234567890', '0987654321'];
  const promises = examplePhoneNumbers.map((phoneNumber, index) => checkMNPStatusAPI(phoneNumber, index));
  Promise.all(promises).then(() => console.log('All MNP statuses updated.'));
};

export default ManageRegistrationScreen;
```

