```powershell
# Function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $users = Get-ADUser -Filter "SID -eq '$sid'" -Properties MemberOf
    $groups = Get-ADGroup -Filter "SID -eq '$sid'" -Properties Members

    foreach ($user in $users) {
        if ($user.MemberOf | Where-Object { $_ -match "^$domain" }) {
            return True
        }
    }

    foreach ($group in $groups) {
        if ($group.Members | Where-Object { $_ -match "^$domain" }) {
            return True
        }
    }

    return False
}

# Function to recursively check folders for ACLs with SIDs in the SIDHistory
function CheckFolderACLs($folderPath) {
    Get-Acl -Path $folderPath | ForEach-Object {
        if ($_.Access | Where-Object { $_.IdentityReference -match "^S-1-5-21-" }) {
            $sid = ($_.Access | Where-Object { $_.IdentityReference -match "^S-1-5-21-" }).IdentityReference

            if (CheckSIDInSIDHistory($sid)) {
                Write-Host "ACL on $folderPath references SID $sid, which is present in the SIDHistory of a domain user or group."
            }
        }
    }

    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        CheckFolderACLs($_.FullName)
    }
}

# Example usage
$folderPath = "C:\Path\To\Your\Folder"
CheckFolderACLs($folderPath)
```

Replace `C:\Path\To\Your\Folder` with the path to the folder you want to check. This script will recursively check all folders and subfolders within the specified path for ACLs that reference SIDs in the SIDHistory of any user or group in the domain.
